CREATE FUNCTION discounted(price numeric, percent integer) RETURNS numeric
    LANGUAGE sql
    RETURN round(price * (100 - percent) / 100, 2);

SELECT name, price, discounted(price, 15) AS sale_price
FROM products
ORDER BY id;

