CREATE FUNCTION label(name text, price numeric, currency text) RETURNS text
    LANGUAGE sql
    RETURN name || ' (' || currency || price || ')';

CREATE OR REPLACE FUNCTION label(name text, price numeric, currency text DEFAULT '$') RETURNS text
    LANGUAGE sql
    RETURN format('%s (%s%s)', name, currency, price);

SELECT label(name, price) AS us_label, label(name, price, 'EUR ') AS eu_label
FROM products
ORDER BY id;

