-- First version: no trimming, no lowercasing, and sep is required
CREATE FUNCTION slug(title text, sep text) RETURNS text
    LANGUAGE sql
    RETURN replace(title, ' ', sep);

CREATE OR REPLACE FUNCTION slug(title text, sep text DEFAULT '-') RETURNS text
    LANGUAGE sql
    RETURN lower(replace(trim(title), ' ', sep));

SELECT name, slug(name) AS slug, slug(name, '_') AS file_name
FROM products
ORDER BY id;

